program BinarySearch;
var
  arr: array[1..10] of integer = (2, 5, 8, 12, 16, 23, 38, 56, 72, 91);
  target, low, high, mid, pos: integer;
  found: boolean;
begin
  target := 23;
  low := 1;
  high := 10;
  found := false;
  pos := -1;
  while (low <= high) and not found do
  begin
    mid := (low + high) div 2;
    if arr[mid] = target then
    begin
      found := true;
      pos := mid;
    end
    else if arr[mid] < target then
      low := mid + 1
    else
      high := mid - 1;
  end;
  if found then
    writeln('Found at index ', pos)
  else
    writeln('Not found');
end.

program BSTDemo;

