program ParityCheck;
var
  n: Integer;
begin
  n := 42; { 42 = 101010 في الثنائي، فيه 3 آحاد }
  { XOR المتتالي لجميع البتات يعطي 1 إذا كان عدد الآحاد فردياً }
  n := n xor (n shr 1);
  n := n xor (n shr 2);
  n := n xor (n shr 4);
  n := n xor (n shr 8);
  n := n xor (n shr 16);
  if (n and 1) = 1 then
    writeln('Odd parity')
  else
    writeln('Even parity');
end.

