program BubbleSort;
var
  arr: array[1..5] of integer = (5, 1, 4, 2, 8);
  i, j, temp: integer;
  swapped: boolean;
begin
  for i := 1 to 4 do
  begin
    swapped := false;
    for j := 1 to 5 - i do
      if arr[j] > arr[j+1] then
      begin
        temp := arr[j];
        arr[j] := arr[j+1];
        arr[j+1] := temp;
        swapped := true;
      end;
    if not swapped then break; { لا تبادل يعني المصفوفة مرتبة }
  end;
  for i := 1 to 5 do
    write(arr[i], ' ');
  writeln;
end.

