program Knapsack;
var
  weights: array[1..3] of integer = (10, 20, 30);
  values: array[1..3] of integer = (60, 100, 120);
  capacity: integer = 50;
  dp: array[0..3, 0..50] of integer;
  i, w: integer;
begin
  for i := 0 to 3 do
    for w := 0 to capacity do
      dp[i][w] := 0;
  for i := 1 to 3 do
    for w := 1 to capacity do
    begin
      if weights[i] <= w then
      begin
        if values[i] + dp[i-1][w-weights[i]] > dp[i-1][w] then
          dp[i][w] := values[i] + dp[i-1][w-weights[i]]
        else
          dp[i][w] := dp[i-1][w];
      end
      else
        dp[i][w] := dp[i-1][w];
    end;
  writeln('Maximum value: ', dp[3][capacity]);
end.

