program MeanStdDev;
const
  N = 5;
  data: array[1..N] of Real = (10.5, 12.3, 9.8, 11.1, 10.9);
var
  sum, mean, variance, stddev: Real;
  i: Integer;
begin
  sum := 0;
  // أولاً نجمع القيم لحساب المتوسط
  for i := 1 to N do
    sum := sum + data[i];
  mean := sum / N;
  variance := 0;
  // ثم نجمع مربعات الفروق عن المتوسط
  for i := 1 to N do
    variance := variance + Sqr(data[i] - mean);
  variance := variance / N;
  stddev := Sqrt(variance);
  writeln('Mean: ', mean:0:2);
  writeln('StdDev: ', stddev:0:2);
end.

