program MergeSort;
var
  arr: array[1..6] of integer = (38, 27, 43, 3, 9, 82);
  temp: array[1..6] of integer;
  i: integer;

procedure Merge(l, m, r: integer);
var
  i, j, k: integer;
begin
  i := l;
  j := m + 1;
  k := l;
  while (i <= m) and (j <= r) do
  begin
    if arr[i] <= arr[j] then
    begin
      temp[k] := arr[i];
      i := i + 1;
    end
    else
    begin
      temp[k] := arr[j];
      j := j + 1;
    end;
    k := k + 1;
  end;
  while i <= m do
  begin
    temp[k] := arr[i];
    i := i + 1;
    k := k + 1;
  end;
  while j <= r do
  begin
    temp[k] := arr[j];
    j := j + 1;
    k := k + 1;
  end;
  for i := l to r do
    arr[i] := temp[i];
end;

procedure MergeSort(l, r: integer);
var
  m: integer;
begin
  if l < r then
  begin
    m := (l + r) div 2;
    MergeSort(l, m);
    MergeSort(m + 1, r);
    Merge(l, m, r);
  end;
end;

begin
