program PascalTriangle;
const
  ROWS = 6;
var
  tri: array[0..ROWS-1, 0..ROWS-1] of Integer;
  i, j: Integer;
begin
  // الحواف تساوي 1، والداخلية مجموع العددين فوقها
  for i := 0 to ROWS-1 do
  begin
    tri[i,0] := 1;
    tri[i,i] := 1;
    for j := 1 to i-1 do
      tri[i,j] := tri[i-1,j-1] + tri[i-1,j];
  end;
  // طباعة المثلث مع مسافات للمحاذاة
  for i := 0 to ROWS-1 do
  begin
    for j := 0 to ROWS-i-2 do
      write(' ');
    for j := 0 to i do
      write(tri[i,j], ' ');
    writeln;
  end;
end.

