program CircularQueueDemo;
const
  SIZE = 5;
var
  q: array[0..SIZE-1] of Integer;
  front, rear, count: Integer;
  i: Integer;
begin
  front := 0; rear := 0; count := 0;
  // إضافة عناصر
  q[rear] := 1; rear := (rear + 1) mod SIZE; Inc(count);
  q[rear] := 2; rear := (rear + 1) mod SIZE; Inc(count);
  q[rear] := 3; rear := (rear + 1) mod SIZE; Inc(count);
  // إزالة عنصر
  front := (front + 1) mod SIZE; Dec(count);
  // طباعة العناصر من الأمام للخلف
  i := front;
  while count > 0 do
  begin
    Write(q[i], ' ');
    i := (i + 1) mod SIZE;
    Dec(count);
  end;
  Writeln;
end.

program QuickSort;
var
  arr: array[1..7] of integer = (10, 7, 8, 9, 1, 5, 3);
  i: integer;

procedure QuickSort(l, r: integer);
var
  pivot, i, j, temp: integer;
begin
  if l < r then
  begin
    pivot := arr[(l + r) div 2];
    i := l;
    j := r;
    while i <= j do
    begin
      while arr[i] < pivot do i := i + 1;
      while arr[j] > pivot do j := j - 1;
      if i <= j then
      begin
        temp := arr[i];
        arr[i] := arr[j];
        arr[j] := temp;
        i := i + 1;
        j := j - 1;
      end;
    end;
    if l < j then QuickSort(l, j);
    if i < r then QuickSort(i, r);
  end;
end;

begin
  QuickSort(1, 7);
  for i := 1 to 7 do
    write(arr[i], ' ');
  writeln;
end.

