  new(newNode);
  newNode^.data := value;
  newNode^.next := head;
  head := newNode;
end;

procedure DeleteValue(value: Integer);
var
  curr, prev: PNode;
begin
  curr := head;
  prev := nil;
  while (curr <> nil) and (curr^.data <> value) do
  begin
    prev := curr;
    curr := curr^.next;
  end;
  if curr = nil then Exit;  // القيمة غير موجودة
  if prev = nil then
    head := curr^.next
  else
    prev^.next := curr^.next;
  dispose(curr);
end;

procedure PrintList;
var
  curr: PNode;
begin
  curr := head;
  while curr <> nil do
  begin
    Write(curr^.data, ' ');
    curr := curr^.next;
  end;
  Writeln;
end;

begin
  head := nil;
  InsertAtHead(3);
  InsertAtHead(2);
  InsertAtHead(1);
  PrintList;          // 1 2 3
  DeleteValue(2);
  PrintList;          // 1 3
end.

program SplitJoin;
var
  s, part, result: string;
  i: integer;
begin
  s := 'apple,banana,cherry';
  result := '';
  part := '';
  for i := 1 to Length(s) + 1 do
  begin
    if (i > Length(s)) or (s[i] = ',') then
    begin
      if result <> '' then
        result := result + ';';
      result := result + part;
      part := '';
    end
    else
      part := part + s[i];
  end;
  writeln(result);
end.

